<?php
require __DIR__.'/config.php';function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$id=filter_input(INPUT_GET,'subject_id',FILTER_VALIDATE_INT)?:1;
if($_SERVER['REQUEST_METHOD']==='POST'){
 $kind=$_POST['kind']??'';
 if($kind==='attendance'){$stmt=$pdo->prepare("INSERT INTO attendance(subject_id,student_id,attendance_date,status) VALUES(?,?,?,?)");$stmt->execute([$id,trim($_POST['student_id']),$_POST['attendance_date'],$_POST['status']]);}
 if($kind==='mark'){$obt=(float)$_POST['obtained'];$max=(float)$_POST['maximum'];if($obt>=0&&$max>0&&$obt<=$max){$stmt=$pdo->prepare("INSERT INTO marks(subject_id,student_id,assessment,obtained,maximum) VALUES(?,?,?,?,?)");$stmt->execute([$id,trim($_POST['student_id']),trim($_POST['assessment']),$obt,$max]);}}
 header('Location: records.php?subject_id='.$id);exit;
}
$stmt=$pdo->prepare("SELECT * FROM attendance WHERE subject_id=? ORDER BY attendance_date DESC");$stmt->execute([$id]);$attendance=$stmt->fetchAll();
$stmt=$pdo->prepare("SELECT * FROM marks WHERE subject_id=? ORDER BY id DESC");$stmt->execute([$id]);$marks=$stmt->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Attendance and marks</title><link rel="stylesheet" href="style.css"></head><body><header><a class="brand" href="index.php?subject_id=<?=$id?>">EduOutcome AI <small>PHP + MySQL</small></a></header><main class="standalone"><h1>Part 6 · Attendance & Marks</h1><div class="grid"><form method="post" class="card"><h2>Attendance</h2><input type="hidden" name="kind" value="attendance"><label>Student ID</label><input name="student_id" required><label>Date</label><input type="date" name="attendance_date" value="<?=date('Y-m-d')?>" required><label>Status</label><select name="status"><option>Present</option><option>Absent</option><option>Late</option></select><button class="primary">Save attendance</button></form><form method="post" class="card"><h2>Marks</h2><input type="hidden" name="kind" value="mark"><label>Student ID</label><input name="student_id" required><label>Assessment</label><input name="assessment" required><div class="fields"><div><label>Obtained</label><input type="number" min="0" step=".5" name="obtained" required></div><div><label>Maximum</label><input type="number" min=".5" step=".5" name="maximum" value="30" required></div></div><button class="primary">Save marks</button></form></div><section class="card"><h2>Attendance log</h2><table><tr><th>Student</th><th>Date</th><th>Status</th></tr><?php foreach($attendance as $r):?><tr><td><?=e($r['student_id'])?></td><td><?=e($r['attendance_date'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></section><section class="card"><h2>Marks register</h2><table><tr><th>Student</th><th>Assessment</th><th>Obtained</th><th>Maximum</th><th>%</th></tr><?php foreach($marks as $r):?><tr><td><?=e($r['student_id'])?></td><td><?=e($r['assessment'])?></td><td><?=e($r['obtained'])?></td><td><?=e($r['maximum'])?></td><td><?=number_format($r['obtained']/$r['maximum']*100,1)?>%</td></tr><?php endforeach;?></table></section></main></body></html>
